package com.delivery.platform.catalog.inventory.api;
import com.delivery.platform.catalog.common.CatalogSupport;import com.delivery.platform.common.ApiException;import com.delivery.platform.identity.security.IdentityPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1/inventory") public class InventoryController {private final JdbcClient db;private final CatalogSupport support;public InventoryController(JdbcClient d,CatalogSupport s){db=d;support=s;}public record Stock(UUID productId,String productName,BigDecimal quantity,BigDecimal lowStockThreshold,boolean lowStock){}public record Adjustment(UUID branchId,UUID productId,UUID variantId,@NotNull @DecimalMin(value="0",inclusive=false)BigDecimal quantity,@Pattern(regexp="INCREASE|DECREASE|ADJUSTMENT|INITIAL")String movementType,String notes){}public record Movement(UUID id,UUID branchId,UUID productId,UUID variantId,String movementType,BigDecimal quantity,BigDecimal previousQuantity,BigDecimal resultingQuantity,Instant createdAt){}
 @GetMapping @PreAuthorize("hasAuthority('CATALOG_INVENTORY_VIEW')") List<Stock> stock(@AuthenticationPrincipal IdentityPrincipal p,@RequestParam(required=false)UUID merchantId){return db.sql("select id,name,coalesce(stock_quantity,0) quantity,low_stock_threshold from products where tenant_id=:t and track_inventory and (cast(:m as uuid) is null or merchant_id=:m) order by name").param("t",p.tenantId()).param("m",merchantId).query((r,n)->{BigDecimal q=r.getBigDecimal("quantity"),low=r.getBigDecimal("low_stock_threshold");return new Stock(r.getObject("id",UUID.class),r.getString("name"),q,low,low!=null&&q.compareTo(low)<=0);}).list();}
 @PostMapping("/adjustments") @Transactional @PreAuthorize("hasAuthority('CATALOG_INVENTORY_ADJUST')") Movement adjust(@AuthenticationPrincipal IdentityPrincipal p,@Valid @RequestBody Adjustment q){if((q.productId()==null)==(q.variantId()==null))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_INVENTORY_ADJUSTMENT","Indica exactamente un producto o una variante");if(q.branchId()!=null)support.branch(p,q.branchId());String table=q.productId()!=null?"products":"product_variants";UUID target=q.productId()!=null?q.productId():q.variantId();String notFound=q.productId()!=null?"PRODUCT_NOT_FOUND":"VARIANT_NOT_FOUND";var current=db.sql("select coalesce(stock_quantity,0) from "+table+" where id=:i and tenant_id=:t for update").param("i",target).param("t",p.tenantId()).query(BigDecimal.class).optional().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,notFound,"Elemento de inventario no encontrado"));BigDecimal result=switch(q.movementType()){case "INCREASE","INITIAL"->current.add(q.quantity());case "DECREASE"->current.subtract(q.quantity());default->q.quantity();};if(result.signum()<0)throw new ApiException(HttpStatus.CONFLICT,"INSUFFICIENT_STOCK","El ajuste dejaría el stock en negativo");db.sql("update "+table+" set stock_quantity=:q,track_inventory=true,updated_at=now() where id=:i").param("q",result).param("i",target).update();UUID id=UUID.randomUUID();db.sql("insert into inventory_movements(id,tenant_id,branch_id,product_id,variant_id,movement_type,quantity,previous_quantity,resulting_quantity,notes,created_by) values(:i,:t,:b,:p,:v,:m,:q,:a,:r,:n,:u)").param("i",id).param("t",p.tenantId()).param("b",q.branchId()).param("p",q.productId()).param("v",q.variantId()).param("m",q.movementType()).param("q",q.quantity()).param("a",current).param("r",result).param("n",q.notes()).param("u",p.userId()).update();support.audit(p,"INVENTORY_ADJUSTED","INVENTORY_MOVEMENT",id);return new Movement(id,q.branchId(),q.productId(),q.variantId(),q.movementType(),q.quantity(),current,result,Instant.now());}
 @GetMapping("/movements") @PreAuthorize("hasAuthority('CATALOG_INVENTORY_VIEW')") List<Movement> movements(@AuthenticationPrincipal IdentityPrincipal p){return db.sql("select id,branch_id,product_id,variant_id,movement_type,quantity,previous_quantity,resulting_quantity,created_at from inventory_movements where tenant_id=:t order by created_at desc limit 200").param("t",p.tenantId()).query(Movement.class).list();}}
